/* ================= 메뉴(아이콘의 기준) ================= */
const MENU=[["운영",[["today","홈","home"],["events","일정","calendar"],["teachers","직원","users"]]],["수업",[["lesson","수업","edit3"],["makeup","보강","repeat"],["records","학습기록","clip"]]],["학생",[["students","학생","user"],["schools","학교","school"],["exams","시험","award"]]],["수강",[["classes","클래스","layers"],["enrolls","등록","usercheck"],["timetable","시간표","grid"]]],["교재",[["subjects","과목","bookmark"],["books","라이브러리","shelf"],["progress","진도","trendup"]]],["보고 · 안내",[["reports","정기 보고서","filetext"],["completion","수료 보고서","checksq"],["letters","가정통신문","mail"]]],["재무",[["tuition","수강료","cash"],["bill","청구서","receipt"],["profit","손익 분석","activity"],["legal","법정 서류","filetext"]]],["설정",[["files","자료실","folder"],["alims","알림톡 설정","msg"],["admin","관리자 설정","settings"]]],["바로가기",[["web:kiosk","출결 키오스크","ext"],["web:classroom","수업 관리","ext"],["web:school","학교 검색","ext"],["web:library","라이브러리 웹 화면","ext"]]],["매뉴얼 · 데이터",[["ext:manual","매뉴얼","ext"],["ext:pubdb","공개 DB","ext"],["ext:privdb","비공개 DB","ext"]]]];
function menuIcon(k){for(const g of MENU)for(const x of g[1])if(x[0]===k)return x[2];return ""}
/* ================= 칸 켜기(실제 자료 모드에서 여는 화면) =================
   목표 사다리의 칸마다 화면 묶음. 출시 판은 원본 검수를 통과한 칸만 GATES_ON에 넣는다(여기 한 곳).
   실제 자료 모드(?live=1)에서만 쓴다 — 꺼진 칸의 화면은 왼쪽 메뉴에서 빠지고 열리지 않는다. 예시 모드는 모두 보인다.
   검수용: 주소에 &gates=P1,P2 처럼 적으면 그 칸들로 연다(출시 전 시험).
   P1 입력 장치 · P2 보기 1:1 · P3 수업(보기만) · P3b 보강 · 학습기록 · P6 옛 HTML 흡수(관리자 설정). 화면 이름 = openScreen에 넘기는 이름.
   P3w(화면 묶음 없음) = 수업 창의 출결 쓰기 — P3과 함께 켤 때만 [출석][결석] · [수업 저장]이 풀린다(live.js). */
const GATES={P1:["teachers","students","schools","glevels","classes","enrolls","timetable","seasons","subjects","areas","books","progress"],
 P2:["today","events","exams","reports","completion","letters","tuition","bill","bookfees","charges","etcs","costs","profit","legal","files","alims"],
 P3:["lesson"],P3b:["makeup","records"],P6:["admin"]};
const GATES_ON=["P1","P2","P3","P2e","P3b","P3w","P3m","P6"];/* 261120 대표: 코드에 저장 길이 있는 기능은 모두 켬(보강 쓰기 P3m 포함) *//* 261120 대표: 관리자 설정 화면은 실제 자료 모드에서도 열림(기능은 없고 기존 웹 화면 admin_settings.html로 가는 카드) *//* 출시 판(261119 원본 검수 통과 칸): P1 입력 + P2 보기 + P3 수업 + P2e 일정 쓰기 + P3b 학습기록 · 루틴 쓰기(보강 화면 읽기) + P3w 출결 쓰기. P3m(보강 쓰기, 끌어놓기 UI는 사람 확인 뒤) · P6은 꺼짐 */
/* 1) 메뉴와 연결된 칸 = 그 메뉴 아이콘(대표 261115). 메뉴 아이콘을 바꾸면 같이 바뀜 */
const MENU_LINK=[[/^(학생|받는 학생|대상 학생|응시 학생|형제자매|형제·자매|학생\(개별일 때\)|학생 이름|학생이름)$/,"students"],[/^(선생님|담당 강사|담당강사|담당자|강사|담당 선생님|담당)$/,"teachers"],[/^(클래스|등록 클래스|수강 클래스|클래스 이름)$/,"classes"],[/^학교$/,"schools"],[/^학년$/,"@gradcap"],[/^시험$/,"exams"],[/^시즌$/,"@gitcommit"]/* 261118: 시즌 메뉴는 일정 › 시즌 탭이라 메뉴 아이콘이 없음 — 시즌 화면 제목 아이콘(gitcommit) 그대로 */,[/^(과목|영역)$/,"subjects"],[/^(교재|프로그램|교재·프로그램)$/,"books"],[/^일정$/,"events"],[/^(보고서|학습 보고서)$/,"reports"],[/^수강료$/,"tuition"],[/^청구$/,"bill"],[/^교재비$/,"bookfees"],[/^등록$/,"enrolls"],[/^시간표$/,"timetable"],[/^가정통신문$/,"letters"],[/^진도$/,"progress"]];
/* 2) 뜻을 보여 주는 예외(대표 지정) — 칸 종류 규칙보다 먼저 */
const ICON_SELECT="downc";/* 고르기 칸(목록에서 하나 고르는 칸: 구분 · 직책 · 사용 · 진행 · 결제 · 상태) 아이콘은 여기 한 곳 — 표 머리 · 창 칸 · 표 편집이 모두 이 값을 쓴다 */
/* 518판(대표 261117 "칸 형식 → 아이콘 한 규칙, 예외 두지 않음"): 고르기 칸은 뜻 아이콘을 따로 두지 않고 모두 ICON_SELECT — 결제 수단 · 문의 경로 · 우선 연락처 · 성별 · 학생과 관계 · 요일 포함 */
const ICON_EXC=[[/상태$|구분$|^결제 수단$|^문의 경로$|^우선 연락처$|^성별$|^학생과 관계$|요일/,ICON_SELECT],[/^메모\(내부용\)$|^메모$|^기록\(내부용\)$|^회의록$/,"lock"],[/안내 메모$/,"msg"],[/^선생님 한마디/,"msgc"],[/^학부모 (공개|리포트)$/,"users"]/* 261118 대표: 눈은 숨김 고르기에만 */,[/^개인정보 동의$/,"shield"],[/^등록 보류$/,"pausec"],[/^주소$/,"mappin"],[/^형제자매$/,"users"]];
/* 3) 칸 종류 규칙 */
function iconRule(label,type){const l=String(label||"").replace(/\s*\(.*\)\s*$/,"").trim(),t=type||"";
  const raw=String(label||"").trim();for(const [re,k] of ICON_EXC)if(re.test(raw)&&FEATHER[k])return k;
  if(t==="won"||/^(수강료|교재비|교습비)$/.test(l))return "won";
  if(/^(달|청구 월|안내월|청구월)$/.test(l))return "calendar";if(/^(종류|항목|기타경비 항목)$/.test(l))return ICON_SELECT;if(/^매달 받는 클래스$/.test(l))return menuIcon("classes");/* 261118(자율): 재무 표 머리 # 대신 뜻 아이콘 *//* 404판(대표): 돈 칸은 메뉴 연결보다 ₩ 먼저 */
  for(const [re,k] of MENU_LINK)if(re.test(l))return k[0]==="@"?k.slice(1):menuIcon(k);
  if(/^(이름|받는 사람)$/.test(l))return "user";
  if(t==="time"||/(등원|하원|시작|끝|수업) ?시간$|시각$/.test(l))return "clock";/* 261118: 시각 칸(시간표 등원시간 · 하원시간) */
  if(t==="date"||t==="datetime"||/일$|일시$|날짜|기간|개강|종강/.test(l))return "calendar";if(t==="tel"||/연락처|전화|발신번호/.test(l))return "phone";if(t==="days"||/요일/.test(l))return ICON_SELECT;
  if(t==="won"||/(금액|가격|재료비|교습비|매출|지출|순이익|손익|합계|단가|할인|미납액|환불액|받을 돈|받은 돈|기타경비|교재비 등|조정)$/.test(l))return "won";if(/분량|범위/.test(l))return "book";if(/전송|안내|전달|템플릿/.test(l))return "msg";
  if(/진행|사용|구분|직책|결제 수단|결제$/.test(l))return ICON_SELECT;return ""}
/* 요소: 그룹|개별 알약 — 그룹 = 여러 사람 + 파랑 바탕, 개별 = 한 사람 + 초록 바탕(글자·아이콘은 색 알약 한 색) */
function modePill(ind){return `<span class="kpl ${ind?"ind":"grp"}">${IC(ind?"user":"users","s")}${ind?"개별":"그룹"}</span>`}
